SELECT TOTLE_TRADE_ID bussinessCode,
       CREATE_USER    createUser,
       CREATE_DEPT    createDept,
       CREATE_TIME    createTime
FROM TRD_FIN_PRODUCT_DEAL_TOTAL
WHERE TRADE_DATE = #{tradeDate}
  AND FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F37}
  AND PS = #{PS_T07}
  AND TG_BUSI_TYPE = #{PINAN_BUSINESS_TYPE_209}
  AND IS_CANCEL = #{YSE_OR_NO_NO}
  AND TRADE_STATUS = #{TRADE_STATUS_01}
